        [Fact]
        public void DumpsMatchesCpythonInEveryMode()
        {
            foreach (var c in Cases)
            {
                JToken v = PyJson.Loads(c.In);
                Assert.Equal(c.DA, PyJson.Dumps(v));
                Assert.Equal(c.DN, PyJson.Dumps(v, ensureAscii: false));
                Assert.Equal(c.CA, PyJson.Compact(v));
                Assert.Equal(c.I2, PyJson.Dumps(v, indent: 2));
                Assert.Equal(c.Sorted, PyJson.Dumps(v, sortKeys: true));
                if (c.Httpx == "ERR") Assert.Throws<ArgumentException>(() => PyJson.HttpxBody(v));
                else Assert.Equal(c.Httpx, PyJson.HttpxBody(v));
            }
        }

        [Fact]
        public void LoadsRejectsWhatPythonRejects()
        {
            foreach (var b in Bad) Assert.Throws<PyJsonException>(() => PyJson.Loads(b));
        }

        [Fact]
        public void HttpxJsonIsUtf8Bytes()
        {
            var o = new JObject { ["s"] = "caf\u00e9", ["n"] = 1.0 };
            Assert.Equal("{\"s\":\"caf\u00e9\",\"n\":1.0}", PyJson.HttpxBody(o));
            Assert.Equal(new byte[] { 0x7b, 0x22, 0x73, 0x22, 0x3a, 0x22, 0x63, 0x61, 0x66, 0xc3, 0xa9, 0x22, 0x2c, 0x22, 0x6e, 0x22, 0x3a, 0x31, 0x2e, 0x30, 0x7d }, PyJson.HttpxJson(o));
        }

        [Fact]
        public void PlainValuesSerialize()
        {
            var d = new Dictionary<string, object> { ["b"] = 1, ["a"] = new List<object> { 1.5, "x", null, true } };
            Assert.Equal("{\"b\": 1, \"a\": [1.5, \"x\", null, true]}", PyJson.Dumps(d));
            Assert.Equal("{\"b\":1,\"a\":[1.5,\"x\",null,true]}", PyJson.Compact(d));
            Assert.Equal("1.0", PyJson.Dumps(1.0));
            Assert.Equal("1e+16", PyJson.Dumps(1e16));
            Assert.Equal("\"\\u00e9\"", PyJson.Dumps("\u00e9"));
        }

        [Theory]
        [InlineData(1.0, "1.0")]
        [InlineData(0.1, "0.1")]
        [InlineData(1e16, "1e+16")]
        [InlineData(1e15, "1000000000000000.0")]
        [InlineData(1e-5, "1e-05")]
        [InlineData(0.0001, "0.0001")]
        [InlineData(1.5e-7, "1.5e-07")]
        [InlineData(-2.5, "-2.5")]
        [InlineData(123456.789, "123456.789")]
        [InlineData(5e-324, "5e-324")]
        public void FloatReprMatchesPython(double d, string want) => Assert.Equal(want, PyJson.FloatRepr(d));

        [Fact]
        public void ReprAndStrOfJsonValues()
        {
            Assert.Equal("{'a': [1, 2.0, None, True, 'x']}", PyJson.Repr(PyJson.Loads("{\"a\": [1, 2.0, null, true, \"x\"]}")));
            Assert.Equal("\"it's\"", PyJson.Repr(new JValue("it's")));
            Assert.Equal("it's", PyJson.Str(new JValue("it's")));
            Assert.Equal("'a\\nb'", PyJson.Repr(new JValue("a\nb")));
        }

        [Fact]
        public void LoadsBytesSkipsBom()
        {
            Assert.Equal(1, (int)PyJson.Loads(new byte[] { 0xEF, 0xBB, 0xBF, (byte)'1' }));
            Assert.Throws<PyJsonException>(() => PyJson.Loads(new byte[] { 0xff, 0xfe, 0x00 }));
        }
